// Song v2 → Strudel code. One block per track; inside it, one layer group per clip and section.
// Each clip is generated by the per-instrument code generator (sceneLayers with `only`).
import { sceneLayers, sectionLane, uniqueNames, sectionInfo, songHeader, rle, ORBIT_OF } from '../music.js';
import { t } from '../i18n.js';
import { normalizeSong, clipState } from './format.js';
import { rackCode } from './rack.js';
import { isSharedName } from './ideas.js';
import { placeSpoken, spokenCode } from './spoken.js';

const fadeIn = (secs, i) => i > 0 ? Math.min(secs[i].fade || 0, secs[i].bars) : 0;

// natural growth (natural-growth): settings a track has not revealed yet leave their functions out of its code,
// so Strudel's defaults apply until a step brings them in. track.hidden: keys of HIDDEN_FNS
export const HIDDEN_FNS = { cutoff: ['lpf'], reso: ['lpq'], drive: ['distort', 'distortvol'], grit: ['crush'], room: ['room', 'roomsize'], delay: ['delay', 'delaysync', 'delayfeedback'], env: ['attack', 'decay', 'sustain', 'release'] };
export function stripFns(line, names) {
  let out = line;
  for (const n of names) {
    for (let at = out.indexOf(`.${n}(`); at >= 0; at = out.indexOf(`.${n}(`, at)) {
      let depth = 0, k = at + n.length + 1;
      for (; k < out.length; k++) { if (out[k] === '(') depth++; else if (out[k] === ')' && --depth === 0) break; }
      out = out.slice(0, at) + out.slice(k + 1);
    }
  }
  return out;
}

// the same, with the text of the functions taken out: { line, cut: ['.lpf(800)', …] }
export function cutFns(line, names) {
  let out = line;
  const cut = [];
  for (const n of names) {
    for (let at = out.indexOf(`.${n}(`); at >= 0; at = out.indexOf(`.${n}(`, at)) {
      if (out.lastIndexOf('//', at) >= 0) break;
      let depth = 0, k = at + n.length + 1;
      for (; k < out.length; k++) { if (out[k] === '(') depth++; else if (out[k] === ')' && --depth === 0) break; }
      cut.push(out.slice(at, k + 1)); out = out.slice(0, at) + out.slice(k + 1);
    }
  }
  return { line: out, cut };
}

export function compileSong(input) {
  const song = normalizeSong(input);
  const secs = song.sections, total = song.total;
  if (!secs.length) throw new Error('a song needs at least one section');
  const v1secs = secs.map(s => ({ bars: s.bars, fade: s.fade, bpm: s.bpm, bpmEnd: s.bpmEnd, meter: s.meter, key: s.key, prog: s.chords }));
  const names = uniqueNames(secs.map(s => s.name));
  const L = songHeader(song.title, v1secs[0], names, v1secs);
  // lanes: one per section (1 plays, 0 silent, values in between fade), as in v1
  const lanes = secs.map((_, i) => sectionLane(v1secs, i));
  L.push('', `// ${t('cSections')}`);
  secs.forEach((s, i) => L.push(`const section${i + 1} = "${rle(lanes[i].map(String))}"  // ${names[i]} · ${sectionInfo({ ...v1secs[i] }, fadeIn(v1secs, i))}`));
  // shared progressions (idea-model): written once, read by name by the tracks that use them
  const shared = song.shared && typeof song.shared === 'object' ? Object.fromEntries(Object.entries(song.shared).filter(([k, v]) => isSharedName(k) && typeof v === 'string')) : {};
  if (Object.keys(shared).length) { L.push('', `// ${t('cShared')}`); for (const [k, v] of Object.entries(shared)) L.push(`const ${k} = "${v}"`); }

  // one bus per track: the first track of a type keeps the v1 orbit, the others get new ones
  const used = new Set();
  let clipLanes = 0, extra = 8;
  // muto e solo: le tracce silenziate non entrano nel codice
  const solo = song.tracks.some(tr => tr.solo);
  // voice instrument (voice-instrument): the lines of the spoken tracks, placed once for the whole song
  const spoken = song.tracks.some(tr => tr.type === 'spoken') ? placeSpoken(input) : [];
  for (const tr of song.tracks) {
    // the bus is chosen before skipping muted tracks, so a track that comes in later (live build) does not move the others
    // (spoken tracks have their own orbits, 13 and 14: they take no bus from the others)
    const orbit = tr.type === 'spoken' ? null : !used.has(tr.type) && ORBIT_OF[tr.type] ? ORBIT_OF[tr.type] : ++extra;
    used.add(tr.type);
    // voice tracks speak the live build comments: their code comes from the build (build.js), not from clips
    if (tr.mute || (solo && !tr.solo) || tr.type === 'voice') continue;
    const first = L.length;
    L.push('', `// ========== ${[...new Set([tr.name || tr.id, tr.type])].join(' · ')} ==========`);
    if (tr.type === 'spoken') {
      L.push(...spokenCode(spoken.filter(p => p.track === tr.id), total));
      if (tr.hush || tr.alone || tr.maskIdea) L.splice(first, L.length - first, ...lineMarks(L.slice(first), tr));
      continue;
    }
    const rack = rackCode(tr.rack, tr.type);
    let described = null;
    for (const clip of tr.clips) {
      const end = clip.start + clip.bars;
      // a clip spanning several sections is compiled piece by piece: each piece follows its section's harmony
      secs.forEach((sec, i) => {
        const a = Math.max(clip.start, sec.start), b = Math.min(end, sec.start + sec.bars);
        if (a >= b) return;
        const whole = a === sec.start && b === sec.start + sec.bars;
        let gate = `section${i + 1}`;
        if (!whole) {
          // part of a section: plays in [a, b), fades in only from a section start, fades out into a fading section
          const v = Array(total).fill(0);
          for (let k = a; k < b; k++) v[k] = 1;
          if (a === sec.start) for (let k = 0; k < fadeIn(v1secs, i); k++) v[a + k] = lanes[i][a + k];
          if (b === sec.start + sec.bars) for (let k = b; k < total && lanes[i][k] > 0; k++) v[k] = lanes[i][k];
          gate = `clip${++clipLanes}`;
          L.push(`const ${gate} = "${rle(v.map(String))}"`);
        }
        L.push(`// ${names[i]} · ${t('cBars', { from: a + 1, to: b })} · ${t('cPattern', { p: clip.pattern })}`);
        const opts = { start: a, bars: b - a, gate, crash: sec.crash && a === sec.start, breath: sec.breath && b === sec.start + sec.bars, fill: sec.fill && b === sec.start + sec.bars, only: tr.type, orbit, rack, shared, variant: Number.isInteger(tr.variant) ? tr.variant : null };
        if (tr.type === 'code') L.push(...codeLayer(tr, clip, gate, orbit, rack));
        else {
          // the instrument comment ("// Bass · Rolling") is repeated per clip only when it changes
          const lines = sceneLayers(clipState(sec, tr, clip), opts).filter(l => l !== '');
          const desc = lines[0] && lines[0].startsWith('//') ? lines.shift() : null;
          if (desc && desc !== described) { L.push(desc); described = desc; }
          const hide = (tr.hidden || []).flatMap(k => HIDDEN_FNS[k] || []), off = (tr.commented || []).filter(k => !(tr.hidden || []).includes(k)).flatMap(k => HIDDEN_FNS[k] || []);
          // commented out (live-coder-growth): the functions leave the chain and stay at the end of their line as a comment
          const out = off.length ? lines.map(l => { const r = cutFns(l, off); return r.cut.length ? `${r.line.trim() ? r.line.replace(/\s+$/, '') : r.line.replace(/\S.*$/, '')} // ${r.cut.join('')}` : l; }) : lines;
          L.push(...(hide.length ? out.map(l => stripFns(l, hide)).filter(l => l.trim() !== '') : out));
        }
      });
    }
    if (tr.hush || tr.alone || tr.maskIdea) L.splice(first, L.length - first, ...lineMarks(L.slice(first), tr));
  }
  return L.join('\n');
}

// growth-shapes: a track's lines muted with "_$:" (hush) or played alone with "S$:" (alone), and a mask idea per phrase
// on each of its layers (before the bus, so the bus and the visual stay last)
export function lineMarks(lines, tr) {
  const out = lines.slice(), label = tr.hush ? '_$:' : tr.alone ? 'S$:' : '$:';
  for (let i = 0; i < out.length; i++) {
    if (!/^\$:/.test(out[i])) continue;
    out[i] = out[i].replace(/^\$:/, label);
    if (!tr.maskIdea) continue;
    let end = i;
    while (end + 1 < out.length && /^\s+\S/.test(out[end + 1]) && !/^\s*\/\//.test(out[end + 1])) end++;
    const mask = `.mask("${tr.maskIdea}")`;
    let done = false;
    for (let k = i; k <= end && !done; k++) { const at = out[k].indexOf('.orbit('); if (at >= 0) { out[k] = out[k].slice(0, at) + mask + out[k].slice(at); done = true; } }
    if (!done) { const c = out[end].indexOf(' // '); out[end] = c >= 0 ? out[end].slice(0, c) + mask + out[end].slice(c) : out[end] + mask; }
    i = end;
  }
  return out;
}

// code track: the pattern is plain Strudel; the app adds the lane, the bus and the visual
function codeLayer(tr, clip, gate, orbit, rack = '') {
  const pat = (tr.patterns || {})[clip.pattern] || {};
  const code = String(pat.code || 'silence').trim().replace(/;\s*$/, '');
  const visual = (tr.settings && tr.settings.visual) || 'fx';
  return [`$: (${code.includes('\n') ? '\n  ' + code.split('\n').join('\n  ') + '\n' : code})`, `  ${rack}.mask(${gate}).velocity(${gate}).orbit(${orbit}).analyze("${visual}")`];
}
